-- Sewa AMP per bulan per BA (ribu Rp) untuk baris "EC exclude Pupuk, Sewa AMP dan Penyusutan" -> work/r_amp.json {ba:[aktual ribu per bulan]}. PMY = 2131+2122, afd B dikeluarkan.
SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, TO_CHAR(DATE_TRUNC('month',BULAN),'YYYY-MM') m, ROUND(SUM(RP_ACTUAL)/1000) a, ROUND(SUM(RP_BUDGET)/1000) b
FROM PRD_DB_PRESENTATION.PRS_COST.ESTATE_COST WHERE KODE_BA IN ('2121','2124','2131','2122') AND NOT (DECODE(KODE_BA,'2122','2131',KODE_BA)='2131' AND KODE_AFD='B') AND GROUP_LEVEL='COST SEWA AMP' AND BULAN>='2026-01-01' AND BULAN<'2026-10-01' GROUP BY 1,2 ORDER BY 1,2;
